import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"Highlight 文本高亮","description":"","frontmatter":{},"headers":[],"relativePath":"components/highlight.md","filePath":"components/highlight.md","lastUpdated":1791177194000}`),l={name:`components/highlight.md`};function u(a,c,l,u,d,f){let p=e(`XhDemo`);return t(),i(`div`,null,[c[0]||=s(`<h1 id="highlight-文本高亮" tabindex="-1">Highlight 文本高亮 <a class="header-anchor" href="#highlight-文本高亮" aria-label="Permalink to “Highlight 文本高亮”">​</a></h1><p>标出一段文本中命中关键词的片段。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/highlight" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/highlight.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/highlight" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/highlight" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/highlight.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>命中关键词的片段渲染为 <code>&amp;lt;mark&gt;</code>，其余是纯文本；整段文本可原样拼接还原</p>`,5),r(p,{src:`highlight/01-basic`}),c[1]||=s(`<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to “组件结构”">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;highlight&quot;</code>：<strong><code>root</code></strong> · <code>mark</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><h3 id="一组关键词" tabindex="-1">一组关键词 <a class="header-anchor" href="#一组关键词" aria-label="Permalink to “一组关键词”">​</a></h3><p>传入数组即可；同一位置多个关键词都命中时取最长的一个，重叠只切出一段</p>`,6),r(p,{src:`highlight/02-keywords`}),c[2]||=o(`h3`,{id:`区分大小写`,tabindex:`-1`},[n(`区分大小写 `),o(`a`,{class:`header-anchor`,href:`#区分大小写`,"aria-label":`Permalink to “区分大小写”`},`​`)],-1),c[3]||=o(`p`,null,`默认不区分，开启 case-sensitive 后按写法比较`,-1),r(p,{src:`highlight/03-case-sensitive`}),c[4]||=o(`h3`,{id:`跟随输入高亮`,tabindex:`-1`},[n(`跟随输入高亮 `),o(`a`,{class:`header-anchor`,href:`#跟随输入高亮`,"aria-label":`Permalink to “跟随输入高亮”`},`​`)],-1),c[5]||=o(`p`,null,`关键词逐字符比对、不拼入正则，输入 . * ( 等字符也只作为普通字符查找`,-1),r(p,{src:`highlight/04-search`}),c[6]||=o(`h3`,{id:`颜色`,tabindex:`-1`},[n(`颜色 `),o(`a`,{class:`header-anchor`,href:`#颜色`,"aria-label":`Permalink to “颜色”`},`​`)],-1),c[7]||=o(`p`,null,`tone 决定命中片段使用哪族颜色，未命中的文本不受影响`,-1),r(p,{src:`highlight/05-tone`}),c[8]||=s(`<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to “设计指引”">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h3><ul><li>在搜索结果、候选列表中标出命中原因。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to “何时不用”">​</a></h3><ul><li>需要富文本或代码着色时，使用<a href="./code-view">代码视图</a>。</li><li>强调一段固定内容时，使用<a href="./typography">排印</a>的 <code>strong</code>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li><code>text</code> 接受单个词或一组词。</li><li><code>caseSensitive</code> 决定是否区分大小写。</li><li>命中片段落在 <code>mark</code> 部件上，样式归皮肤。</li><li><code>tone</code> 决定命中片段的颜色族，落在 <code>root</code> 上：一段内有多个命中，语气是整段的属性。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to “组合”">​</a></h3><ul><li>放入<a href="./combobox">组合框</a>的候选、<a href="./table">表格</a>的单元格、<a href="./list">列表</a>的条目标题。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li>高亮只用底色，不同时改字色与字重，避免一句话中出现过多重音。</li><li>关键词很短（一两个字符）时考虑不高亮，命中会过于分散。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to “反模式”">​</a></h3><ul><li>用它做正文重点标注：那属于内容，不是检索反馈。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to “产物”">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-highlight&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhHighlight</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/highlight.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to “Props”">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>caseSensitive</code></td><td><code>boolean</code></td><td></td><td>区分大小写，默认不区分。</td></tr><tr><td><code>keyword</code></td><td><code>string | readonly string[]</code></td><td></td><td>关键词，一个或一组。空串会被丢弃。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td></td><td>要显示的整段文本。命中位置按该串逐字符计算。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定命中片段使用哪族颜色。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to “connect API”">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code></td><td>解析后的文本；未提供时为空串。</td></tr><tr><td><code>segments</code></td><td><code>readonly HighlightSegment[]</code></td><td>切分后的片段，依次拼接恒等于 text。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMarkProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>铺到每个命中片段上的属性；每段相同，命中的是哪个关键词不写入 DOM。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to “无障碍”">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to “键盘”">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to “样式参考”">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to “皮肤”">​</a></h3><p><code>@xihan-ui/styles/highlight.css</code> 按 <code>[data-scope=&quot;highlight&quot;][data-part=&quot;root&quot;]</code> 部件选择器书写，发布产物以挂载类 <code>.xh-scope-highlight</code> 代替其中的 data-scope（特异性相同），位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>，部件选择器照常可用。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to “数据属性”">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-case-sensitive</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to “CSS 变量”">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-highlight-mark-bg</code></td><td><code>mark</code><br><code>root</code></td><td><code>background</code></td><td><code>default</code><br><code>tone</code></td><td><code>--xh-_tone-subtle</code><br><code>--xh-bg-brand-subtle</code></td><td>highlight 的 mark、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-highlight-mark-fg</code></td><td><code>mark</code><br><code>root</code></td><td><code>color</code></td><td><code>default</code><br><code>tone</code></td><td><code>--xh-_tone-fg</code><br><code>--xh-fg-brand-strong</code></td><td>highlight 的 mark、root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-highlight-mark-font-weight</code></td><td><code>mark</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-medium</code></td><td>highlight 的 mark 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-highlight-mark-px</code></td><td><code>mark</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>highlight 的 mark 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-highlight-mark-radius</code></td><td><code>mark</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>highlight 的 mark 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to “动效”">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to “RTL”">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>`,38)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};